## ---- 01: Implementation  (qmd line 32) ----------------------------------------------

library(oasr)

compute_eff_duration <- function(cashflows, rate_paths, oas, h_bp = 25) {
  h <- h_bp / 10000
  shift_paths <- function(r, s) {
    r$yield_paths <- lapply(r$yield_paths, function(M) M + s)
    r
  }
  pv_total <- function(r)
    sum(calculate_present_value(cashflows, r, oas,
                                asset_level = FALSE, total_idx = 5)$mean_pvs)
  V0 <- pv_total(rate_paths)
  Vp <- pv_total(shift_paths(rate_paths, +h))
  Vm <- pv_total(shift_paths(rate_paths, -h))
  -(Vp - Vm) / (2 * h * V0)
}


