## ---- 05: Key-Rate Durations (User Helper Built on `oasr` Primitives)  (qmd line 405) -

# Didactic KRD: discount the path-average pool cashflow off the reference
# path, bumping only the months that fall in a bucket around each key tenor
krd_by_bucket <- function(cf_vec, times, rate_paths, oas_bps,
                           tenors = c(2, 5, 10, 30), h_bp = 25) {
  h   <- h_bp / 10000
  ref <- extract_reference_rates(rate_paths, "10")
  oas <- oas_bps / 10000
  pv  <- function(bump) {
    mean(apply(ref[, seq_along(times), drop = FALSE], 1, function(r)
      sum(cf_vec * exp(-(r + oas + bump) * times))))
  }
  edges <- c(0, head(tenors, -1) + diff(tenors) / 2, Inf)
  V0 <- pv(0)
  sapply(seq_along(tenors), function(j) {
    w <- as.numeric(times > edges[j] & times <= edges[j + 1])
    -(pv(+h * w) - pv(-h * w)) / (2 * h * V0)
  })
}

pool_cf_vec <- rowMeans(sapply(pool_cf, function(a) rowSums(a[, 5, ])))
times       <- seq_along(pool_cf_vec) / 12
krd_vec <- krd_by_bucket(pool_cf_vec, times, rate_paths,
                          oas_result$oas, tenors = c(2, 5, 10, 30))
sum(krd_vec)


## ---- 06: Prepayment Duration (User Helper)  (qmd line 434) ---------------------------

prepay_duration <- function(asset_data, rate_paths, prepay_mod,
                             oas, ppc_bump = 0.10) {
  bump_ppc <- function(mult) {
    pm <- prepay_mod
    pm$base_cpr <- pm$base_cpr * mult
    pm
  }
  ref <- extract_reference_rates(rate_paths, "10")
  value_at <- function(pm) {
    cv <- calculate_credit_vectors(asset_data, rate_paths, pm)
    cf <- aggregate_cashflows(project_cashflows(asset_data, cv,
                               reference_rates = ref),
                              asset_data, deal_structure)
    sum(calculate_present_value(cf, rate_paths, oas,
                                asset_level = FALSE, total_idx = 5)$mean_pvs)
  }
  V0 <- value_at(prepay_mod)
  Vp <- value_at(bump_ppc(1 + ppc_bump))
  Vm <- value_at(bump_ppc(1 - ppc_bump))
  -(Vp - Vm) / (2 * ppc_bump * V0)
}


## ---- 07: Scenario Stress (User Helper)  (qmd line 460) -------------------------------

shift_all_tenors <- function(rate_paths, shift_dec) {
  rate_paths$yield_paths <- lapply(rate_paths$yield_paths,
                                   function(M) M + shift_dec)
  rate_paths
}

scenarios <- list(
  parallel_p100 = function(r) shift_all_tenors(r, +0.01),
  parallel_m100 = function(r) shift_all_tenors(r, -0.01)
)

stress_results <- lapply(scenarios, function(fn) {
  r_shocked <- fn(rate_paths)
  sum(calculate_present_value(pool_cf, r_shocked, oas = oas_result$oas,
                              asset_level = FALSE, total_idx = 5)$mean_pvs)
})


## ---- 08: P&L Attribution  (qmd line 481) ---------------------------------------------

attribute_pnl <- function(dV, sensitivities, market_moves) {
  parts <- list(
    duration   = -sensitivities$D    * market_moves$parallel,
    convexity  =  0.5 * sensitivities$C * market_moves$parallel^2,
    kr_residual = sum(sensitivities$krd *
                      (market_moves$kr - market_moves$parallel)),
    spread     = -sensitivities$Dspr * market_moves$spread
  )
  c(parts, list(residual = dV - sum(unlist(parts))))
}


